/**
 * @description Tests for IH_SelfTestKit: echo, REJECT, DOWN, payload build and response handler. No callouts and no
 * reliance on org data; a Case is created when the org allows it.
 */
@IsTest
private class IH_SelfTestKitTest {

    private static final String USER_DOMAIN = '@ihselftest.example.com';

    @TestSetup
    static void setup() {
        List<Profile> profiles = [SELECT Id FROM Profile WHERE Name = 'Standard User' WITH SYSTEM_MODE LIMIT 1];
        Id profileId = profiles.isEmpty() ? UserInfo.getProfileId() : profiles[0].Id;
        String unique = EncodingUtil.convertToHex(Crypto.generateAesKey(128)).left(10);
        User tester = new User(LastName = 'IH Self Tester', Alias = unique.left(8), Email = unique + '@example.com',
            Username = unique + '.selftester' + USER_DOMAIN, ProfileId = profileId, EmailEncodingKey = 'UTF-8',
            LanguageLocaleKey = 'en_US', LocaleSidKey = 'en_US', TimeZoneSidKey = 'America/Chicago');
        System.runAs(new User(Id = UserInfo.getUserId())) {
            insert tester;
        }
    }

    private static User tester() {
        String pattern = '%.selftester' + USER_DOMAIN;
        return [SELECT Id FROM User WHERE Username LIKE :pattern WITH SYSTEM_MODE LIMIT 1];
    }

    private static IntegrationHub.InboundContext context(String eventKey) {
        IntegrationHub.InboundContext ctx = new IntegrationHub.InboundContext();
        ctx.eventKey = eventKey;
        ctx.body = '{"caseNumber":"00001"}';
        ctx.data = new Map<String, Object>{ 'caseNumber' => '00001' };
        ctx.headers = new Map<String, String>{ 'Content-Type' => 'application/json' };
        return ctx;
    }

    @IsTest
    static void echoSucceedsWithReference() {
        System.runAs(tester()) {
            Test.startTest();
            IntegrationHub.InboundResult result = new IH_SelfTestKit().handle(context('SELF_ECHO'));
            Test.stopTest();
            Assert.isTrue(result.success, 'the echo succeeds');
            Assert.areEqual(200, result.statusCode, 'the echo answers 200');
            Assert.isNull(result.recordId, 'no recordId in the body links no record');
            Map<String, Object> echo = (Map<String, Object>) result.data;
            Assert.areEqual('SELF_ECHO', echo.get('eventKey'), 'the event key is echoed');
            Assert.isTrue(echo.containsKey('inboundTransactionId'), 'the inbound transaction Id is echoed');
            Assert.areEqual('00001', ((Map<String, Object>) echo.get('received')).get('caseNumber'), 'the body is echoed');
            Assert.isTrue(String.valueOf(echo.get('reference')).startsWith(IH_SelfTestKit.REFERENCE_PREFIX), 'a reference is returned');
            Assert.areNotEqual(IH_SelfTestKit.shortUnique(), IH_SelfTestKit.shortUnique(), 'each reference is unique');
        }
    }

    @IsTest
    static void echoLinksTheSentRecord() {
        System.runAs(tester()) {
            Id sent = UserInfo.getUserId();
            IntegrationHub.InboundContext ctx = context('SELF_ECHO');
            ctx.data.put('recordId', String.valueOf(sent));
            Assert.areEqual(sent, new IH_SelfTestKit().handle(ctx).recordId, 'the echo links the sent record');
            ctx.data.put('recordId', 'not-an-id');
            Assert.isNull(IH_SelfTestKit.sentRecordId(ctx), 'an invalid Id links nothing');
            ctx.data.put('recordId', 5);
            Assert.isNull(IH_SelfTestKit.sentRecordId(ctx), 'a value that is not text links nothing');
        }
    }

    @IsTest
    static void createModeMakesACase() {
        System.runAs(tester()) {
            IntegrationHub.InboundContext ctx = context('SELF_CASE_CREATE');
            Assert.areEqual(400, new IH_SelfTestKit().handle(ctx).statusCode, 'no Subject answers 400');
            ctx.data = new Map<String, Object>{ 'fields' => new Map<String, Object>{ 'Subject' => 'Self create', 'Origin' => 'Web' } };
            Test.startTest();
            IntegrationHub.InboundResult result = new IH_SelfTestKit().handle(ctx);
            Test.stopTest();
            if (result.success) {
                Assert.areEqual(Case.SObjectType, result.recordId.getSObjectType(), 'a Case is created and linked');
            } else {
                Assert.areEqual(422, result.statusCode, 'a Case the org refuses answers 422');
            }
        }
    }

    @IsTest
    static void nullContextStillEchoes() {
        System.runAs(tester()) {
            IntegrationHub.InboundResult result = new IH_SelfTestKit().handle((IntegrationHub.InboundContext) null);
            Assert.isTrue(result.success, 'a null call is treated as an echo');
        }
    }

    @IsTest
    static void rejectFailsWith422() {
        System.runAs(tester()) {
            IntegrationHub.InboundResult result = new IH_SelfTestKit().handle(context('SELF_REJECT'));
            Assert.isFalse(result.success, 'a reject fails');
            Assert.areEqual(IH_SelfTestKit.REJECT_STATUS, result.statusCode, 'a reject answers 422');
            Assert.areEqual(IH_SelfTestKit.REJECT_MESSAGE, result.message, 'the reject text is returned');
        }
    }

    @IsTest
    static void downFailsWith503() {
        System.runAs(tester()) {
            IntegrationHub.InboundResult result = new IH_SelfTestKit().handle(context('self_down'));
            Assert.isFalse(result.success, 'down fails');
            Assert.areEqual(IH_SelfTestKit.DOWN_STATUS, result.statusCode, 'down answers 503');
            Assert.areEqual(IH_SelfTestKit.DOWN_MESSAGE, result.message, 'the down text is returned');
        }
    }

    @IsTest
    static void buildMakesOneBodyPerCase() {
        List<Id> caseIds = new List<Id>();
        System.runAs(new User(Id = UserInfo.getUserId())) {
            try {
                Case c = new Case(Subject = 'IH self-test case');
                insert c;
                caseIds.add(c.Id);
            } catch (DmlException e) {
                caseIds.clear();
            }
        }
        System.runAs(tester()) {
            IntegrationHub.PayloadRequest req = new IntegrationHub.PayloadRequest();
            req.eventKey = 'SELF_SEND_CLASS';
            req.relatedObject = 'Case';
            req.recordIds = caseIds;
            Map<Id, Object> bodies = new IH_SelfTestKit().build(req);
            Assert.areEqual(caseIds.size(), bodies.size(), 'one body per existing Case');
            for (Id caseId : bodies.keySet()) {
                Map<String, Object> body = (Map<String, Object>) bodies.get(caseId);
                Assert.areEqual(IH_SelfTestKit.SOURCE, body.get('source'), 'the source is set');
                Assert.areEqual(caseId, body.get('caseId'), 'the Case Id is set');
                Assert.isTrue(body.containsKey('subject'), 'the subject is set');
                Assert.isNotNull(body.get('caseNumber'), 'the Case number is set');
            }
            Assert.isTrue(new IH_SelfTestKit().build(null).isEmpty(), 'no request gives no bodies');
            Assert.isTrue(new IH_SelfTestKit().build(new IntegrationHub.PayloadRequest()).isEmpty(), 'no Ids give no bodies');
        }
    }

    @IsTest
    static void responseHandlerOnlyLogs() {
        System.runAs(tester()) {
            IntegrationHub.ResponseContext ctx = new IntegrationHub.ResponseContext();
            ctx.txn = new IH_Transaction__c(Status__c = IntegrationHub.STATUS_SENT);
            ctx.httpStatus = 200;
            ctx.body = '{"status":"Success"}';
            Integer dmlBefore = Limits.getDmlStatements();
            new IH_SelfTestKit().handle(ctx);
            new IH_SelfTestKit().handle((IntegrationHub.ResponseContext) null);
            Assert.areEqual(IntegrationHub.STATUS_SENT, ctx.txn.Status__c, 'the handler changes nothing');
            Assert.areEqual(dmlBefore, Limits.getDmlStatements(), 'the handler does no DML');
        }
    }
}
